CREATE TABLE IF NOT EXISTS public.lab_result_notifications ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hospital_id UUID NOT NULL REFERENCES hospitals(id) ON DELETE CASCADE, lab_result_id UUID NOT NULL REFERENCES lab_results(id) ON DELETE CASCADE, patient_id UUID NOT NULL REFERENCES patients(id), ordering_doctor_id UUID NOT NULL REFERENCES profiles(id), status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'notified', 'acknowledged', 'acted_upon', 'cancelled')), notification_method TEXT, is_critical BOOLEAN DEFAULT FALSE, requires_immediate_action BOOLEAN DEFAULT FALSE, notified_at TIMESTAMPTZ, acknowledged_at TIMESTAMPTZ, acknowledged_by UUID REFERENCES profiles(id), acted_upon_at TIMESTAMPTZ, action_notes TEXT, consent_logged BOOLEAN DEFAULT FALSE, consent_logged_at TIMESTAMPTZ, metadata JSONB DEFAULT '{}', created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now() ); ALTER TABLE public.lab_result_notifications ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "lab_result_notifications_hospital_scope" ON lab_result_notifications; CREATE POLICY "lab_result_notifications_hospital_scope" ON public.lab_result_notifications USING (hospital_id = (SELECT hospital_id FROM profiles WHERE id = auth.uid())); DROP POLICY IF EXISTS "lab_result_notifications_doctor_access" ON lab_result_notifications; CREATE POLICY "lab_result_notifications_doctor_access" ON public.lab_result_notifications USING ( auth.uid() IN ( SELECT ordering_doctor_id FROM public.lab_result_notifications WHERE id = lab_result_notifications.id UNION SELECT acknowledged_by FROM public.lab_result_notifications WHERE id = lab_result_notifications.id AND acknowledged_by IS NOT NULL ) OR auth.uid() IN ( SELECT ur.user_id FROM user_roles ur WHERE ur.role IN ('admin') ) ); CREATE INDEX IF NOT EXISTS idx_lab_result_notifications_hospital ON public.lab_result_notifications(hospital_id, status); CREATE INDEX IF NOT EXISTS idx_lab_result_notifications_doctor ON public.lab_result_notifications(ordering_doctor_id, status); CREATE INDEX IF NOT EXISTS idx_lab_result_notifications_pending ON public.lab_result_notifications(hospital_id) WHERE status IN ('pending', 'notified'); DROP TRIGGER IF EXISTS lab_result_notifications_moddatetime ON public.lab_result_notifications; CREATE TRIGGER lab_result_notifications_moddatetime BEFORE UPDATE ON public.lab_result_notifications FOR EACH ROW EXECUTE FUNCTION public.touch_row_updated_at(); DROP TRIGGER IF EXISTS lab_result_notifications_audit ON public.lab_result_notifications; CREATE TABLE IF NOT EXISTS public.lab_critical_alerts ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hospital_id UUID NOT NULL REFERENCES hospitals(id) ON DELETE CASCADE, lab_result_id UUID NOT NULL REFERENCES lab_results(id) ON DELETE CASCADE, patient_id UUID NOT NULL REFERENCES patients(id), test_code TEXT NOT NULL, test_name TEXT NOT NULL, result_value NUMERIC NOT NULL, critical_range_id UUID REFERENCES public.lab_critical_ranges(id), severity TEXT NOT NULL DEFAULT 'critical_high' CHECK (severity IN ('critical_high', 'critical_low', 'warning')), primary_doctor_id UUID NOT NULL REFERENCES profiles(id), primary_notified_at TIMESTAMPTZ, primary_acknowledged_at TIMESTAMPTZ, primary_action_taken BOOLEAN DEFAULT FALSE, primary_action_notes TEXT, on_call_id UUID REFERENCES profiles(id), on_call_notified_at TIMESTAMPTZ, on_call_acknowledged_at TIMESTAMPTZ, on_call_action_taken BOOLEAN DEFAULT FALSE, on_call_action_notes TEXT, er_notified_at TIMESTAMPTZ, er_acknowledged_at TIMESTAMPTZ, er_action_taken BOOLEAN DEFAULT FALSE, er_action_notes TEXT, is_resolved BOOLEAN DEFAULT FALSE, resolved_at TIMESTAMPTZ, resolved_by UUID REFERENCES profiles(id), resolution_notes TEXT, metadata JSONB DEFAULT '{}', created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now() ); ALTER TABLE public.lab_critical_alerts ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "lab_critical_alerts_hospital_scope" ON lab_critical_alerts; CREATE POLICY "lab_critical_alerts_hospital_scope" ON public.lab_critical_alerts USING (hospital_id = (SELECT hospital_id FROM profiles WHERE id = auth.uid())); DROP POLICY IF EXISTS "lab_critical_alerts_clinical_access" ON lab_critical_alerts; CREATE POLICY "lab_critical_alerts_clinical_access" ON public.lab_critical_alerts USING ( auth.uid() IN ( SELECT primary_doctor_id FROM public.lab_critical_alerts WHERE id = lab_critical_alerts.id UNION SELECT on_call_id FROM public.lab_critical_alerts WHERE id = lab_critical_alerts.id AND on_call_id IS NOT NULL ) OR auth.uid() IN ( SELECT ur.user_id FROM user_roles ur WHERE ur.role IN ('admin', 'doctor', 'nurse') ) ); CREATE INDEX IF NOT EXISTS idx_lab_critical_alerts_hospital ON public.lab_critical_alerts(hospital_id, is_resolved); CREATE INDEX IF NOT EXISTS idx_lab_critical_alerts_unresolved ON public.lab_critical_alerts(hospital_id) WHERE is_resolved = FALSE; CREATE INDEX IF NOT EXISTS idx_lab_critical_alerts_primary_doctor ON public.lab_critical_alerts(primary_doctor_id, is_resolved); DROP TRIGGER IF EXISTS lab_critical_alerts_moddatetime ON public.lab_critical_alerts; CREATE TRIGGER lab_critical_alerts_moddatetime BEFORE UPDATE ON public.lab_critical_alerts FOR EACH ROW EXECUTE FUNCTION public.touch_row_updated_at(); DROP TRIGGER IF EXISTS lab_critical_alerts_audit ON public.lab_critical_alerts; INSERT INTO public.lab_critical_ranges (hospital_id, test_code, test_name, critical_low, critical_high, warning_low, warning_high, unit_of_measure, age_group, gender, notes, created_by) SELECT h.id, v.test_code, v.test_name, v.critical_low, v.critical_high, v.warning_low, v.warning_high, v.unit, v.age_group, v.gender, v.notes, (SELECT id FROM public.profiles ORDER BY created_at LIMIT 1) FROM hospitals h CROSS JOIN (VALUES ('2345-7','Glucose',40,400,70,200,'mg/dL','adult','both','Hypoglycemia or hyperglycemia crisis threshold'), ('2757-9','Potassium (K+)',2.5,6.5,3.5,5.5,'mEq/L','adult','both','Severe hypokalemia/hyperkalemia risk arrhythmia'), ('2951-2','Sodium (Na+)',120,160,130,150,'mEq/L','adult','both','Severe hyponatremia/hypernatremia seizure risk'), ('1975-2','Troponin I',NULL,0.04,NULL,0.02,'ng/mL','adult','both','Acute MI indicator - critical if >0.04')) AS v(test_code,test_name,critical_low,critical_high,warning_low,warning_high,unit,age_group,gender,notes) WHERE NOT EXISTS (SELECT 1 FROM public.lab_critical_ranges r WHERE r.hospital_id = h.id AND r.test_code = v.test_code);